sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {
    g_form.hideFieldMsg('vehicle', true);

    if (isLoading || !newValue) return;

    var ga = new GlideAjax('x_2220337_vehicl_0.VehicleUtilsAjax');
    ga.addParam('sysparm_name', 'getVehicleDetails');
    ga.addParam('sysparm_vehicle', newValue);

    ga.getXMLAnswer(function(answer) {
        if (!answer) return;

        var v = JSON.parse(answer);
        g_form.setValue('customer', v.ownerId, v.ownerName);

        g_form.showFieldMsg(
            'vehicle',
            v.model + ' | Last service: ' + v.lastService,
            'info'
        );

        if (v.premium) {
            g_form.showFieldMsg(
                'vehicle',
                'Premium customer: request will be set to High priority',
                'error'
            );
        }
    });
}
